WITH "_src_normalized" AS (SELECT LOWER(TRIM(BOTH '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM "src"."code")) AS "code", CASE WHEN COLLATE(LOWER(CASE WHEN COLLATE("src"."status" || '|', 'case_sensitive') IN (COLLATE('N/A' || '|', 'case_sensitive'), COLLATE('' || '|', 'case_sensitive')) THEN NULL ELSE "src"."status" END) || '|', 'case_sensitive') = COLLATE('A' || '|', 'case_sensitive') THEN 'Active' WHEN COLLATE(LOWER(CASE WHEN COLLATE("src"."status" || '|', 'case_sensitive') IN (COLLATE('N/A' || '|', 'case_sensitive'), COLLATE('' || '|', 'case_sensitive')) THEN NULL ELSE "src"."status" END) || '|', 'case_sensitive') = COLLATE('I' || '|', 'case_sensitive') THEN 'Inactive' WHEN COLLATE(LOWER(CASE WHEN COLLATE("src"."status" || '|', 'case_sensitive') IN (COLLATE('N/A' || '|', 'case_sensitive'), COLLATE('' || '|', 'case_sensitive')) THEN NULL ELSE "src"."status" END) || '|', 'case_sensitive') = COLLATE('O''Brien' || '|', 'case_sensitive') THEN 'Quoted' ELSE LOWER(CASE WHEN COLLATE("src"."status" || '|', 'case_sensitive') IN (COLLATE('N/A' || '|', 'case_sensitive'), COLLATE('' || '|', 'case_sensitive')) THEN NULL ELSE "src"."status" END) END AS "status", TRIM(BOTH '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM "src"."city") AS "city", TRIM(LEADING '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM "src"."first") AS "first", TRIM(TRAILING '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM "src"."last") AS "last", CASE WHEN "src"."score" IN (-1) THEN NULL ELSE "src"."score" END AS "score" FROM "shop"."orders_v1" AS "src"), "_tgt_normalized" AS (SELECT LOWER(TRIM(BOTH '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM "tgt"."code")) AS "code", LOWER(CASE WHEN COLLATE("tgt"."status" || '|', 'case_sensitive') IN (COLLATE('N/A' || '|', 'case_sensitive'), COLLATE('' || '|', 'case_sensitive')) THEN NULL ELSE "tgt"."status" END) AS "status", TRIM(BOTH '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM "tgt"."city") AS "city", TRIM(LEADING '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM "tgt"."first") AS "first", TRIM(TRAILING '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM "tgt"."last") AS "last", CASE WHEN "tgt"."score" IN (-1) THEN NULL ELSE "tgt"."score" END AS "score" FROM "shop"."orders_v2" AS "tgt") SELECT "src"."code" AS "_veridelta_key_0", "src"."status" AS "_veridelta_source_0", "tgt"."status" AS "_veridelta_target_0", COALESCE((COLLATE("src"."status" || '|', 'case_sensitive') = COLLATE("tgt"."status" || '|', 'case_sensitive') OR ("src"."status" IS NULL AND "tgt"."status" IS NULL)), FALSE) AS "_veridelta_match_0", "src"."city" AS "_veridelta_source_1", "tgt"."city" AS "_veridelta_target_1", COALESCE((COLLATE("src"."city" || '|', 'case_sensitive') = COLLATE("tgt"."city" || '|', 'case_sensitive') OR ("src"."city" IS NULL AND "tgt"."city" IS NULL)), FALSE) AS "_veridelta_match_1", "src"."first" AS "_veridelta_source_2", "tgt"."first" AS "_veridelta_target_2", COALESCE((COLLATE("src"."first" || '|', 'case_sensitive') = COLLATE("tgt"."first" || '|', 'case_sensitive') OR ("src"."first" IS NULL AND "tgt"."first" IS NULL)), FALSE) AS "_veridelta_match_2", "src"."last" AS "_veridelta_source_3", "tgt"."last" AS "_veridelta_target_3", COALESCE((COLLATE("src"."last" || '|', 'case_sensitive') = COLLATE("tgt"."last" || '|', 'case_sensitive') OR ("src"."last" IS NULL AND "tgt"."last" IS NULL)), FALSE) AS "_veridelta_match_3", "src"."score" AS "_veridelta_source_4", "tgt"."score" AS "_veridelta_target_4", COALESCE(("src"."score" = "tgt"."score" OR ("src"."score" IS NULL AND "tgt"."score" IS NULL)), FALSE) AS "_veridelta_match_4" FROM "_src_normalized" AS "src" INNER JOIN "_tgt_normalized" AS "tgt" ON COLLATE("src"."code" || '|', 'case_sensitive') = COLLATE("tgt"."code" || '|', 'case_sensitive') WHERE NOT (COALESCE((COLLATE("src"."status" || '|', 'case_sensitive') = COLLATE("tgt"."status" || '|', 'case_sensitive') OR ("src"."status" IS NULL AND "tgt"."status" IS NULL)), FALSE) AND COALESCE((COLLATE("src"."city" || '|', 'case_sensitive') = COLLATE("tgt"."city" || '|', 'case_sensitive') OR ("src"."city" IS NULL AND "tgt"."city" IS NULL)), FALSE) AND COALESCE((COLLATE("src"."first" || '|', 'case_sensitive') = COLLATE("tgt"."first" || '|', 'case_sensitive') OR ("src"."first" IS NULL AND "tgt"."first" IS NULL)), FALSE) AND COALESCE((COLLATE("src"."last" || '|', 'case_sensitive') = COLLATE("tgt"."last" || '|', 'case_sensitive') OR ("src"."last" IS NULL AND "tgt"."last" IS NULL)), FALSE) AND COALESCE(("src"."score" = "tgt"."score" OR ("src"."score" IS NULL AND "tgt"."score" IS NULL)), FALSE)) ORDER BY "_veridelta_key_0" LIMIT 5
